        fun of(key: String?): Sticker? = entries.firstOrNull { it.key == key }

        /** A sticker at random, one of those not in [used] while any is left. */
        fun random(used: Collection<String> = emptyList()): String =
            (entries.filter { it.key !in used }.ifEmpty { entries }).random().key
